// Output follows the Notify subflow contract: to, title, message, icon, channel,
// persistent, sticky, extraData (tag, color, group, progress, chronometer, ...).
const MODES = {
    grill: 'Grill', smoker: 'Smoker', bake: 'Bake', roast: 'Roast',
    broil: 'Broil', dehydrate: 'Dehydrate', reheat: 'Reheat',
    'air crisp': 'Air Crisp', griddle: 'Griddle',
};
const TAG = 'woodfire_progress';
const probeTag = (i) => `woodfire_probe${i}`;

const ev = msg.payload.event || {};
const type = msg.payload.event_type || msg.topic;
const now = Math.floor(Date.now() / 1000);
const mins = (s) => Math.max(0, Math.round((s || 0) / 60));
const probeName = (i) => `Probe ${(i || 0) + 1}`;

// Grill mode reports the firmware's internal °C target; show the heat level instead.
function target() {
    const sp = ev.setpoint;
    if (sp === undefined || sp === null) return '';
    if (ev.mode !== 'grill') return ` at ${sp}°C`;
    const level = sp <= 3 ? sp : sp < 175 ? 1 : sp < 215 ? 2 : 3;
    return ` · ${['Low', 'Medium', 'High'][level - 1]}`;
}
const label = () => (MODES[ev.mode] || ev.mode || 'Cook') + target();

function note(title, message, opts) {
    // Generic HA notify payload. The `data` keys follow the companion-app
    // (mobile_app) notification conventions: tag, color, group, channel,
    // sticky, chronometer, when, alert_once, progress, progress_max.
    const { icon = 'mdi:grill', persistent = false, sticky = false, ...extra } = opts;
    return {
        title, message,
        data: { group: 'woodfire_cook', channel: 'woodfire', sticky,
                notification_icon: icon, ...extra },
    };
}
// clear_notification is a mobile_app feature: it dismisses a tagged notification.
const clear = (tag) => ({ message: 'clear_notification', data: { tag } });

function build() {
    switch (type) {
        case 'ninja_woodfire_cook_started':
            return [note('🔥 Grill started',
                `${label()} · ${mins(ev.seconds_set)} min${ev.smoke ? ' · 🌲 Smoke' : ''}\nPreheating…`,
                { color: '#ff6b35', tag: TAG, persistent: true, sticky: true, alert_once: true,
                  progress: -1, chronometer: true, when: now })];
        case 'ninja_woodfire_preheat_complete':
            // The cook timer starts once preheat ends: count down to the end.
            return [note('✅ Preheat complete', `${label()}\nAdd your food now!`,
                { color: '#4caf50', tag: TAG, persistent: true, sticky: true, alert_once: false,
                  ...(ev.seconds_set ? { chronometer: true, when: now + ev.seconds_set } : {}) })];
        case 'ninja_woodfire_cook_halftime':
            return [note('⏱️ Halfway', `${mins(ev.seconds_left)} min left · time to flip?`,
                { color: '#ff9800', tag: TAG, persistent: true, sticky: true, alert_once: false,
                  progress: (ev.seconds_set || 0) - (ev.seconds_left || 0), progress_max: ev.seconds_set || 1,
                  chronometer: true, when: now + (ev.seconds_left || 0) })];
        case 'ninja_woodfire_probe_halfway': {
            const current = Math.round(ev.current || 0);
            return [note(`🌡️ ${probeName(ev.probe_index)} halfway there`,
                `${current}°C of ${ev.target}°C · ${Math.max(0, ev.target - current)}°C to go`,
                { icon: 'mdi:thermometer', color: '#2196f3', tag: probeTag(ev.probe_index),
                  persistent: true, sticky: true, alert_once: false,
                  progress: current, progress_max: ev.target || 1 })];
        }
        case 'ninja_woodfire_probe_target_reached':
            return [note(`✅ ${probeName(ev.probe_index)} done`,
                `Target temperature ${ev.target}°C reached 🎯 (currently ${Math.round(ev.current || 0)}°C)`,
                { icon: 'mdi:check-circle', color: '#4caf50', tag: probeTag(ev.probe_index) })];
        case 'ninja_woodfire_cook_done': {
            const done = ev.reason !== 'stopped';
            // Replace the progress notification and clear leftover probe progress.
            return [
                note(done ? '🎉 Grill done' : '⏹️ Grill stopped',
                    done ? 'All done! Enjoy your meal 🍖' : 'The cook was ended.',
                    { color: done ? '#4caf50' : '#ff9800', tag: TAG }),
                clear(probeTag(0)),
                clear(probeTag(1)),
            ];
        }
        case 'ninja_woodfire_prompt': {
            const PROMPTS = {
                addfood: ['\ud83c\udf57 Add food', 'Preheat done \u2014 add your food now!'],
                flipfood: ['\ud83d\udd04 Flip', 'Time to flip your food.'],
                getfood: ['\ud83c\udf7d\ufe0f Remove', 'Remove your food.'],
                closelid: ['\ud83d\udd3d Close lid', 'Please close the lid.'],
                done: ['\u2705 Done', 'Cook complete.'],
            };
            const pr = PROMPTS[ev.prompt] || [`Notice: ${ev.prompt}`, ''];
            return [note(pr[0], pr[1], { icon: 'mdi:bell-ring', color: '#ff9800',
                tag: 'woodfire_prompt', persistent: true, sticky: true })];
        }
        default:
            return [];
    }
}

const msgs = build();
// Emit one message per notification on the single output.
return msgs.length ? [msgs.map((m) => ({ ...msg, payload: m }))] : null;
